// ================== EDIT THIS VALUE ==================
const TELEGRAM_CHAT_ID = 'YOUR_TELEGRAM_CHAT_ID';
// =====================================================
const d = $input.first().json;
const ex = d.execution || {};
const wf = d.workflow || {};

// The backup workflow already sent its own alert before this node ran → don't send a duplicate.
if (ex.lastNodeExecuted === 'Mark execution as failed') return [];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let msg = (ex.error && (ex.error.message || ex.error.description)) ||
          (d.trigger && d.trigger.error && d.trigger.error.message) || 'No error message';
if (msg.length > 1500) msg = msg.slice(0, 1500) + '…';

const when = $now.setZone('Asia/Kathmandu').toFormat('yyyy-MM-dd HH:mm');
const lines = [
  `🚨 <b>Workflow crashed</b>`,
  `📄 Workflow: <b>${esc(wf.name || 'unknown')}</b> (${esc(wf.id || '?')})`,
  `🗓 ${when} (Asia/Kathmandu)`,
  `🧩 Last node: <b>${esc(ex.lastNodeExecuted || (d.trigger ? 'trigger' : 'unknown'))}</b>`,
  `💬 Error: ${esc(msg)}`,
  ...(ex.url ? [`🔎 Execution: <a href="${esc(ex.url)}">open in n8n</a>`] : []),
];
return [{ json: { chatId: TELEGRAM_CHAT_ID, text: lines.join('\n') } }];
